!function(e){"use strict";const n=new e.DOPAdapter({dataModel:{count:0},behaviorModel:{increment:e=>({...e,count:e.count+1}),decrement:e=>({...e,count:e.count-1})}});function t(){const e=n.getState();document.getElementById("counter-value").innerText=e.count}document.addEventListener("DOMContentLoaded",function(){t(),document.getElementById("increment-btn").addEventListener("click",()=>{n.applyTransition("increment"),t()}),document.getElementById("decrement-btn").addEventListener("click",()=>{n.applyTransition("decrement"),t()})})}(obix);
